[{"tool_name": "write", "arguments": {"path": "/tmp/chisle-ablation-work-03dXUv/server.js", "contents": "import express from 'express';
import sqlite3 from 'sqlite3';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { body, validationResult } from 'express-validator';

const app = express();
const db = new sqlite3.Database(':memory:');
const SECRET = 'your-secret-key-change-in-production';
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_ATTEMPTS = 5;

const loginAttempts = new Map(); // email -> { count, resetTime }

app.use(express.json());

// Initialize database
db.run(`
  CREATE TABLE users (
    id INTEGER PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

// Middleware: Check rate limit
const checkRateLimit = (email) => {
  const now = Date.now();
  const attempt = loginAttempts.get(email);

  if (!attempt) return { allowed: true };
  if (now > attempt.resetTime) {
    loginAttempts.delete(email);
    return { allowed: true };
  }
  if (attempt.count >= MAX_ATTEMPTS) {
    return { allowed: false, retryAfter: Math.ceil((attempt.resetTime - now) / 1000) };
  }
  return { allowed: true };
};

// Middleware: Record failed login
const recordFailedLogin = (email) => {
  const attempt = loginAttempts.get(email) || { count: 0, resetTime: Date.now() + RATE_LIMIT_WINDOW };
  attempt.count++;
  loginAttempts.set(email, attempt);
};

// Middleware: Verify JWT
const verifyToken = (req, res, next) => {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: 'Missing token' });

  const token = auth.split(' ')[1];
  jwt.verify(token, SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// POST /signup
app.post(
  '/signup',
  body('email').isEmail(),
  body('password').isLength({ min: 8 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    const passwordHash = await bcrypt.hash(password, 10);

    db.run('INSERT INTO users (email, password_hash) VALUES (?, ?)', [email, passwordHash], (err) => {
      if (err) return res.status(400).json({ error: 'Email already exists' });
      res.json({ message: 'Signup successful' });
    });
  }
);

// POST /login
app.post(
  '/login',
  body('email').isEmail(),
  body('password').notEmpty(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    const rateLimit = checkRateLimit(email);
    if (!rateLimit.allowed) {
      return res.status(429).json({ error: 'Too many attempts', retryAfter: rateLimit.retryAfter });
    }

    db.get('SELECT * FROM users WHERE email = ?', [email], async (err, user) => {
      if (err) return res.status(500).json({ error: 'Server error' });
      if (!user) {
        recordFailedLogin(email);
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const valid = await bcrypt.compare(password, user.password_hash);
      if (!valid) {
        recordFailedLogin(email);
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      loginAttempts.delete(email);
      const token = jwt.sign({ id: user.id, email: user.email }, SECRET, { expiresIn: '7d' });
      res.json({ token });
    });
  }
);

// GET /protected (example)
app.get('/protected', verifyToken, (req, res) => {
  res.json({ message: `Hello ${req.user.email}` });
});

app.listen(3000, () => console.log('Server on port 3000'));
"}}]
